# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZ İBADETİNİN BİREYE KAZANDIRDIKLARI (DKAB.5.2.3)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Manevi Huzur ve Bilinç</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Allah (c.c.) ile bağ kurmayı sağlar.</text>\n  <text x="125" y="128" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Kalbe güven, ümit ve huzur verir.</text>\n  <text x="125" y="154" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Nimetlere şükür bilinci kazandırır.</text>\n  <text x="125" y="180" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Sabır ve tevekkül duygusunu güçlendirir.</text>\n  <text x="125" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">«Namaz müminin miracıdır.»</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Temizlik ve Zaman Disiplini</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11.5" fill="#14532d">• Günde 5 kez abdestle beden arınır.</text>\n  <text x="350" y="128" text-anchor="middle" font-size="11.5" fill="#14532d">• Elbise ve çevre temizliği alışkanlık olur.</text>\n  <text x="350" y="154" text-anchor="middle" font-size="11.5" fill="#14532d">• Vakit şartı zamanı planlamayı öğretir.</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11.5" fill="#14532d">• Sorumluluk ve öz düzenleme gelişir.</text>\n  <text x="350" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Nisâ 103: Belirli vakitlerde farzdır.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Güzel Ahlak ve Davranış</text>\n  <text x="575" y="102" text-anchor="middle" font-size="11.5" fill="#78350f">• İnsanı kötülüklerden alıkoyar.</text>\n  <text x="575" y="128" text-anchor="middle" font-size="11.5" fill="#78350f">• Yalan, hile ve kırıcılıktan uzak tutar.</text>\n  <text x="575" y="154" text-anchor="middle" font-size="11.5" fill="#78350f">• Tevazu (alçak gönüllülük) kazandırır.</text>\n  <text x="575" y="180" text-anchor="middle" font-size="11.5" fill="#78350f">• Dürüst ve güvenilir olmayı destekler.</text>\n  <text x="575" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Ankebût 45: Kötülükten uzaklaştırır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZIN TOPLUMSAL FAYDALARI VE CEMAAT BİLİNCİ</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="180" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Birlik, Kardeşlik ve Eşitlik</text>\n  <text x="180" y="104" text-anchor="middle" font-size="12" fill="#831843">• Camide aynı kıbleye yönelen müminler</text>\n  <text x="180" y="126" text-anchor="middle" font-size="12" fill="#831843">omuz omuza aynı safta eşitlenir.</text>\n  <text x="180" y="154" text-anchor="middle" font-size="12" fill="#831843">• Zengin-fakir, genç-yaşlı ayrımı kalkar;</text>\n  <text x="180" y="176" text-anchor="middle" font-size="12" fill="#831843">kibir ve üstünlük duygusu silinir.</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Toplumsal barış ve sevgi güçlenir.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Yardımlaşma ve Dayanışma</text>\n  <text x="520" y="104" text-anchor="middle" font-size="12" fill="#155e75">• Cuma, bayram ve teravih namazlarında</text>\n  <text x="520" y="126" text-anchor="middle" font-size="12" fill="#155e75">komşular ve akrabalar bir araya gelir.</text>\n  <text x="520" y="154" text-anchor="middle" font-size="12" fill="#155e75">• Hastalar ziyaret edilir, ihtiyaç sahipleri</text>\n  <text x="520" y="176" text-anchor="middle" font-size="12" fill="#155e75">fark edilerek yardımlaşma sağlanır.</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Namaz sonunda sağa ve sola selam (barış) verilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİR DUA TANIYORUM: TAHİYYAT (ETTEHİYYÂTÜ) DUASI (DKAB.5.2.4)</text>\n  <rect x="20" y="46" width="330" height="194" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="185" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Tahiyyat Duasının Okunuşu</text>\n  <text x="185" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">«Ettehiyyâtü lillâhi vessalevâtü vettayyibât.</text>\n  <text x="185" y="120" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Esselâmü aleyke eyyühen-nebiyyü</text>\n  <text x="185" y="144" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">ve rahmetullâhi ve berekâtüh.</text>\n  <text x="185" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Esselâmü aleynâ ve alâ ibâdillâhis-sâlihîn.</text>\n  <text x="185" y="192" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Eşhedü en lâ ilâhe illallah ve eşhedü</text>\n  <text x="185" y="214" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">enne Muhammeden abdühû ve resûlüh.»</text>\n\n  <rect x="365" y="46" width="315" height="194" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="522" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Nerede Okunur ve Ne Anlama Gelir?</text>\n  <text x="522" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Namazların ilk oturuşunda (ka\'de-i ûlâ)</text>\n  <text x="522" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">ve son oturuşunda (ka\'de-i ahîre) okunur.</text>\n  <text x="522" y="144" text-anchor="middle" font-size="11.5" fill="#166534">• Sözlü, bedeni ve mali bütün ibadetlerin</text>\n  <text x="522" y="164" text-anchor="middle" font-size="11.5" fill="#166534">Allah\'a (c.c.) mahsus olduğunu bildirir.</text>\n  <text x="522" y="190" text-anchor="middle" font-size="11.5" fill="#166534">• Hz. Peygamber\'e ve salih kullara selam verir,</text>\n  <text x="522" y="212" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Kelime-i Şehadet ile tevhit inancını ikrar eder.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
